referenceSolutions.javascript:
export function sortedSquares(values          )           {
  const result = Array        (values.length); let left = 0, right = values.length-1; for (let i = values.length-1; i >= 0; i--) { if (Math.abs(values[left]) > Math.abs(values[right])) result[i] = values[left++] ** 2; else result[i] = values[right--] ** 2; } return result;
}

